#!/usr/bin/env node
/**
 * Tests for tools/cost-audit.mjs. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * A tiny fabricated projects tree in a temp dir, shaped like the harness's transcripts: a main session
 * with three turns (one above 200k, one above 300k), a repeated assistant message, a Skill and an MCP
 * call, hook injections and an old turn outside the window; a subagent transcript; a done-claim log.
 * The clock is fixed with `now`, so the window is deterministic.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { audit, report } from './cost-audit.mjs';

const TOOL = join(dirname(fileURLToPath(import.meta.url)), 'cost-audit.mjs');
const NOW = Date.parse('2026-10-22T12:00:00Z');
const created = [];
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

const at = (daysAgo) => new Date(NOW - daysAgo * 864e5).toISOString();
const turn = (id, daysAgo, { input = 0, create = 0, read = 0 }, content = [], extra = {}) => ({
  type: 'assistant', timestamp: at(daysAgo), ...extra,
  message: { id, role: 'assistant', content, usage: { input_tokens: input, cache_creation_input_tokens: create, cache_read_input_tokens: read } },
});
const use = (id, name, input = {}) => ({ type: 'tool_use', id, name, input });
const hook = (daysAgo, hookEvent, text) => ({
  type: 'attachment', timestamp: at(daysAgo), attachment: { type: 'hook_additional_context', hookEvent, content: [text] },
});

function fixture() {
  const root = mkdtempSync(join(tmpdir(), 'cost-'));
  created.push(root);
  const project = join(root, 'projects', 'proj-a');
  mkdirSync(join(project, 'sess-1', 'subagents'), { recursive: true });
  const write = (file, entries) => writeFileSync(file, entries.map((e) => JSON.stringify(e)).join('\n') + '\n');
  write(join(project, 'sess-1.jsonl'), [
    hook(1, 'SessionStart', '⏱ Ore non registrate su 1 giorno: 2026-10-01 (x) — chiudili con /worklog <data>.'),
    hook(1, 'UserPromptSubmit', 'Contesto a 210k token. A fine risposta, una riga.'),
    hook(1, 'SessionStart', 'something unrecognised'),
    turn('m1', 1, { input: 2, create: 40_000, read: 10_000 }, [use('t1', 'Skill', { skill: 'commit' })]),
    // the same message written again for its second content block: counted once
    turn('m1', 1, { input: 2, create: 40_000, read: 10_000 }, [use('t2', 'mcp__srv-a__query')]),
    turn('m2', 1, { input: 1, read: 250_000 }, [use('t3', 'mcp__srv-a__query'), use('t4', 'Skill', { skill: 'commit' })]),
    turn('m3', 1, { input: 1, read: 350_000 }),
    turn('old', 40, { input: 5, read: 900_000 }, [use('t5', 'Skill', { skill: 'old-skill' })]),
  ]);
  // a subagent: its tool calls count, its tokens do not
  write(join(project, 'sess-1', 'subagents', 'agent-x.jsonl'), [
    turn('s1', 1, { input: 1, read: 500_000 }, [use('t6', 'mcp__srv-b__go')], { isSidechain: true }),
  ]);
  const log = join(root, 'done-claim.log');
  writeFileSync(log, [
    { at: at(2), rule: 'claim-without-evidence', word: 'Fatto' },
    { at: at(3), rule: 'shell-ran', word: 'fatto' },
    { at: at(60), rule: 'claim-without-evidence', word: 'done' },
  ].map((r) => JSON.stringify(r)).join('\n') + '\n');
  return { projects: join(root, 'projects'), log };
}

test('baseline is the first assistant message of each session in the window', () => {
  const { projects, log } = fixture();
  const r = audit({ projects, log, now: NOW });
  assert.equal(r.sessions.length, 1);
  assert.equal(r.sessions[0].baseline, 50_002);
  assert.equal(r.sessions[0].session, 'sess-1');
});

test('the share of input tokens in turns above 200k and 300k; repeats and subagents do not count', () => {
  const { projects, log } = fixture();
  const { share } = audit({ projects, log, now: NOW });
  assert.equal(share.turns, 3);
  assert.equal(share.total, 50_002 + 250_001 + 350_001);
  assert.deepEqual(share.over, [250_001 + 350_001, 350_001]);
});

test('skill loads, MCP calls (subagents included), hook injections and the done-claim log, all windowed', () => {
  const { projects, log } = fixture();
  const r = audit({ projects, log, now: NOW });
  assert.deepEqual([...r.skills], [['commit', 2]]);
  assert.deepEqual(Object.fromEntries(r.mcp), { 'srv-a': 2, 'srv-b': 1 });
  assert.deepEqual(Object.fromEntries(r.hooks), { 'worklog-pending': 1, 'context-nudge': 1, 'SessionStart (other)': 1 });
  assert.deepEqual(Object.fromEntries(r.doneClaim), { 'claim-without-evidence / fatto': 1, 'shell-ran / fatto': 1 });
});

test('a wider window brings the old turn back', () => {
  const { projects, log } = fixture();
  const r = audit({ projects, log, now: NOW, days: 90 });
  assert.equal(r.skills.get('old-skill'), 1);
  assert.equal(r.doneClaim.get('claim-without-evidence / done'), 1);
});

test('the CLI prints the report; a missing directory is exit 2', () => {
  const { projects, log } = fixture();
  const ok = spawnSync(process.execPath, [TOOL, '--projects', projects, '--log', log, '--now', new Date(NOW).toISOString()], { encoding: 'utf8' });
  assert.equal(ok.status, 0, ok.stderr);
  assert.match(ok.stdout, /sessions 1, min 50k, median 50k, max 50k/);
  assert.match(ok.stdout, /context > 200k: 92\.3 %/);
  assert.match(ok.stdout, /2\s+commit/);
  const bad = spawnSync(process.execPath, [TOOL, '--projects', join(projects, 'nope')], { encoding: 'utf8' });
  assert.equal(bad.status, 2);
  assert.match(report(audit({ projects, log, now: NOW })), /# Cost audit - last 30 days/);
});

test('a session that began before the window has no baseline: its first message is outside it', () => {
  const { projects, log } = fixture();
  const file = join(projects, 'proj-b.jsonl');
  writeFileSync(file, [
    turn('b1', 40, { input: 1, create: 30_000 }),
    turn('b2', 1, { input: 1, read: 120_000 }),
  ].map((e) => JSON.stringify(e)).join('\n') + '\n');
  const r = audit({ projects, log, now: NOW });
  assert.deepEqual(r.sessions.map((s) => s.session), ['sess-1']);
  assert.equal(r.share.turns, 4, 'its in-window turn still counts towards the context shares');
});

test('--help prints the usage and exits 0', () => {
  for (const flag of ['--help', '-h']) {
    const r = spawnSync(process.execPath, [TOOL, flag], { encoding: 'utf8' });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /^usage: node cost-audit\.mjs/);
  }
});

test('the unproven-row and tail-truncated done-claim rules are counted with the row state as word', () => {
  const { projects, log } = fixture();
  const day = at(1);
  writeFileSync(log, [
    { at: day, rule: 'unproven-row', word: 'fatto' },
    { at: day, rule: 'unproven-row', word: 'fatto' },
    { at: day, rule: 'tail-truncated', word: 'failed' },
  ].map((r) => JSON.stringify(r)).join('\n') + '\n');
  const r = audit({ projects, log, now: NOW });
  assert.deepEqual(Object.fromEntries(r.doneClaim), { 'unproven-row / fatto': 2, 'tail-truncated / failed': 1 });
  assert.match(report(r), /2\s+unproven-row \/ fatto/);
});
